p=argparse.ArgumentParser();p.add_argument('--asset',required=True);p.add_argument('--report',required=True);a=p.parse_args(sys.argv[sys.argv.index('--')+1:]);d=Path(a.asset);info=json.loads((d/'model-info.json').read_text());bpy.ops.wm.open_mainfile(filepath=str(d/'scene.blend'));s=bpy.context.scene;cam=s.camera;expected=info['studio']['views']['beauty'];target=Vector(expected['target']);expected_rot=(target-Vector(expected['location'])).to_track_quat('-Z','Y');direction=cam.rotation_euler.to_quaternion()@Vector((0,0,-1));expected_dir=(target-Vector(expected['location'])).normalized();ob=next(o for o in s.objects if o.type=='MESH' and o.name.startswith('ORISON'));m=ob.data.materials[0].node_tree.nodes.get('Principled BSDF');checks={'blender_432':tuple(bpy.app.version)==(4,3,2),'renderer_CPU':s.render.engine=='CYCLES' and s.cycles.device=='CPU','one_camera':len([o for o in s.objects if o.type=='CAMERA'])==1,'lights_3':len([o for o in s.objects if o.type=='LIGHT'])==3,'model_and_ground_only':len([o for o in s.objects if o.type=='MESH'])==2,'beauty_camera_position':(cam.location-Vector(expected['location'])).length<1e-7,'beauty_camera_direction':(direction-expected_dir).length<1e-6,'beauty_orthographic':cam.data.type=='ORTHO' and abs(cam.data.ortho_scale-expected['ortho_scale'])<1e-7,'render_size':s.render.resolution_x==info['studio']['resolution'][0] and s.render.resolution_y==info['studio']['resolution'][1],'samples_match':s.cycles.samples==info['studio']['samples'],'seed_zero':s.cycles.seed==0 and not s.cycles.use_animated_seed,'fixed_sampling_no_denoise':not s.cycles.use_adaptive_sampling and not s.cycles.use_denoising,'AgX_exposure':s.view_settings.view_transform=='AgX' and s.view_settings.exposure==0,'relative_render_path':s.render.filepath=='//beauty.png','material_linear_color':max(abs(x-y) for x,y in zip(m.inputs['Base Color'].default_value[:3],info['material']['base_color_linear']))<1e-6,'material_roughness':abs(m.inputs['Roughness'].default_value-info['material']['roughness'])<1e-6}
report={'passed':all(checks.values()),'variant':info['variant'],'checks':checks,'scene_sha256':hashlib.sha256((d/'scene.blend').read_bytes()).hexdigest(),'info_sha256':hashlib.sha256((d/'model-info.json').read_bytes()).hexdigest(),'checker_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'saved_camera':{'location':list(cam.location),'direction':list(direction),'ortho_scale':cam.data.ortho_scale},'limits':['This independently reopens the actual saved scene and checks its beauty camera.','Other generated views are declared by generator configuration and separately visually inspected; this does not claim six independently saved camera scenes.','Not GPU, dynamic aliasing or photographic material calibration.']};Path(a.report).write_text(json.dumps(report,indent=2));print('PHOTO',report['passed']);raise SystemExit(0 if report['passed'] else 1)
